import { describe, expect, it } from 'vitest';
import * as docs from './docs';

/**
 * "문서" 탭의 순수 함수(docs.ts)를 Rust로 옮기면서(ADR-191 3k) JS와 Rust가 다르게 읽기 쉬운 입력을 고정한다.
 * 기대값은 옮기기 전 TS 구현이 낸 값이다(JSON.stringify 글자 — 키 순서 포함). "의도한 차이"라고 적은 벡터만 옛 구현과 다르다:
 * 짝 없는 서로게이트는 napi 경계에서 U+FFFD가 되고, 색인 정렬의 localeCompare는 ASCII·한글 음절만 ICU와 같으며(한자·악센트·정규화 다른 글자는 코드 포인트 순서),
 * 색인 요약의 필드가 글자가 아니면 던진다. 보이지 않는 글자는 \u 이스케이프로 적었다.
 * 특수한 값은 표시 객체로 적는다: {"$num":"NaN"}(NaN·Infinity·-0), {"$date":"ISO"}(잘못된 Date는 "invalid"), {"$undef":true}(undefined), {"$json":"…"}(JSON.parse한 값).
 *
 * 경로 안전 벡터(slugifyTitle·designDocFilePath·adrFilePath): `../`, `a/b`, 역슬래시, 점뿐인 제목, 유니코드 구분자, 5000자 제목을 넣었다.
 * 번호 벡터: 번호 0, 99→100, 앞자리 0, 겹치는 꼴, `./` 접두, 대소문자가 다른 `adr`. 마커 영역 벡터: 없음·하나만·뒤집힘·두 번·코드 블록 안.
 */

interface Vector {
  fn: string;
  note: string;
  args: unknown[];
  expected?: unknown;
  throws?: true;
}

function revive(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(revive);
  if (value !== null && typeof value === 'object') {
    const record = value as Record<string, unknown>;
    if ('$num' in record) return Number(record['$num']);
    if ('$date' in record) return record['$date'] === 'invalid' ? new Date(Number.NaN) : new Date(record['$date'] as string);
    if ('$undef' in record) return undefined;
    if ('$json' in record) return JSON.parse(record['$json'] as string); // `__proto__` 같은 키를 소스의 객체 리터럴로 쓰면 프로토타입이 되므로 JSON으로 적는다
    return Object.fromEntries(Object.entries(record).map(([key, item]) => [key, revive(item)]));
  }
  return value;
}

const IMPLS = docs as unknown as Record<string, (...args: unknown[]) => unknown>;

