describe('docs 벡터(옛 TS 구현이 낸 값)', () => {
  for (const [index, vector] of VECTORS.entries()) {
    it(`${index} ${vector.fn}: ${vector.note}`, () => {
      const impl = IMPLS[vector.fn]!;
      const args = revive(vector.args) as unknown[];
      if (vector.throws) {
        expect(() => impl(...args)).toThrow();
        return;
      }
      const actual = impl(...args);
      const expected = revive(vector.expected);
      expect(JSON.stringify(actual)).toBe(JSON.stringify(expected));
      if (typeof expected === 'number') expect(Object.is(actual, expected)).toBe(true); // NaN·-0 구별
    });
  }

  it('벡터가 비지 않았고 함수마다 있다', () => {
    expect(VECTORS.length).toBeGreaterThan(400);
    const names = new Set(VECTORS.map((vector) => vector.fn));
    for (const name of ['slugifyTitle', 'nextDesignDocNumber', 'nextAdrNumber', 'designDocFilePath', 'adrFilePath', 'buildDesignDocTemplate', 'buildAdrTemplate', 'buildTroubleshootingEntry', 'appendTroubleshootingEntry', 'buildRoadmapTradeoffEntry', 'appendRoadmapTradeoffEntry', 'buildVerificationEntry', 'appendVerificationEntry', 'buildExperimentEntry', 'appendExperimentEntry', 'buildRoadmapTemplate', 'regenerateRoadmapStatus', 'extractDocSummary', 'buildDocSummary', 'regenerateDocsReadme']) {
      expect(names.has(name), name).toBe(true);
    }
  });
});
